const skin=mat('#d99068'), shirt=mat('#e5b34f'), pants=mat('#4e6d68'), shoe=mat('#37483e');
box(playerModel,0,.98,0,.72,.82,.44,shirt);box(playerModel,0,.56,.01,.58,.35,.42,mat('#fff0d6'));box(playerModel,-.2,.34,0,.2,.48,.25,pants);box(playerModel,.2,.34,0,.2,.48,.25,pants);box(playerModel,-.2,.1,.07,.27,.15,.4,shoe);box(playerModel,.2,.1,.07,.27,.15,.4,shoe);sphere(playerModel,0,1.58,0,.32,skin);cylinder(playerModel,0,1.84,0,.36,.38,.16,mat('#df815c'));box(playerModel,0,1.9,-.03,.62,.12,.48,mats.green);box(playerModel,0,1.35,.24,.3,.43,.045,mats.cream);sphere(playerModel,-.11,1.63,.285,.035,mats.black);sphere(playerModel,.11,1.63,.285,.035,mats.black);box(playerModel,0,1.52,.29,.12,.025,.02,mats.red);
