const customerColors=[mat('#d77f62'),mat('#729bb2'),mat('#ba8dbb'),mat('#debd62'),mat('#8dab78'),mat('#e39a69')];
const customers=[];let queue=[];let nextSpawn=3,completed=0,served=0,earnings=0,supplies=54,carried=0,gameSeconds=0,started=false,dayWon=false;
const money=n=>'$'+Math.floor(n).toLocaleString();
function makeCustomer(){const g=new THREE.Group();const c=customerColors[Math.floor(Math.random()*customerColors.length)];const skinTone=[mat('#d99a75'),mat('#efc09d'),mat('#9e654c'),mat('#d99a75')][Math.floor(Math.random()*4)];box(g,0,.88,0,.63,.7,.4,c);box(g,0,.48,.02,.44,.28,.35,mat('#566e62'));box(g,-.16,.27,0,.16,.42,.18,mat('#4f5551'));box(g,.16,.27,0,.16,.42,.18,mat('#4f5551'));box(g,-.16,.07,.05,.22,.12,.3,mats.black);box(g,.16,.07,.05,.22,.12,.3,mats.black);sphere(g,0,1.43,0,.27,skinTone);cylinder(g,0,1.63,0,.29,.3,.12,[mats.orange,mats.blue,mats.green,mats.red][Math.floor(Math.random()*4)]);const bag=box(g,.4,.5,.1,.28,.3,.12,mats.cream);bag.visible=false;g.userData.bag=bag;scene.add(g);
  const stocked=shelves.filter(s=>s.stock>0);const shelf=stocked.length?stocked[Math.floor(Math.random()*stocked.length)]:shelves[Math.floor(Math.random()*shelves.length)];const cst={group:g,x:(Math.random()-.5)*5,z:8.1,state:'toShelf',shelf,wait:2+Math.random()*2,bag:false,phase:0};g.position.set(cst.x,0,cst.z);customers.push(cst);return cst}
function refreshQueue(){queue.forEach((c,i)=>{if(c.state==='queue'){c.target={x:7.7,z:3.85+i*1.08}}})}
function setStockVisual(s){const amount=Math.ceil(s.stock/s.max*s.products.length);s.products.forEach((p,i)=>{p.visible=i<amount})}
shelves.forEach(setStockVisual);
function spawnCustomer(){if(customers.filter(c=>c.state!=='leave').length>=6)return;makeCustomer()}
function near(a,b,r){return Math.hypot(a.x-b.x,a.z-b.z)<r}
function currentInteraction(){let best=null;const distance=(x,z)=>Math.hypot(player.position.x-x,player.position.z-z);
 const dSupply=distance(-10,6);if(dSupply<2.1)best={d:dSupply,title:'Pick up supplies',detail:`${carried?`Carrying ${carried} items`:supplies?`${supplies} items in stock`:'Out of supplies'}` ,action:'supply'};
 for(const s of shelves){const d=distance(s.x,s.z+1.1);if(d<1.85&&d<(best?.d??Infinity))best={d,title:carried?'Restock shelf':'Check shelf',detail:carried?`${carried} items in your crate · ${s.stock}/${s.max} full`:`${s.stock}/${s.max} items · ${supplies?'Pick up a crate first':'No supplies left'}`,action:'shelf',shelf:s}}
 const dTill=distance(8.7,7.7);const waiting=queue.length;if(dTill<2.5&&dTill<(best?.d??Infinity))best={d:dTill,title:waiting?'Serve next customer':'Checkout counter',detail:waiting?`${waiting} shopper${waiting>1?'s':''} ready to pay`:'Customers will line up here',action:'checkout'};
 return best}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2100)}
function interact(){const it=currentInteraction();if(!it){toast('Move closer to a shelf, supplies, or checkout!');return}
 if(it.action==='supply'){if(carried){toast(`You’re already carrying ${carried} items!`);return}if(!supplies){toast('The supply crate is empty for now.');return}carried=Math.min(8,supplies);supplies-=carried;toast(`Picked up ${carried} fresh items!`)}
 if(it.action==='shelf'){if(!carried){toast('Pick up a crate of supplies first.');return}if(it.shelf.stock>=it.shelf.max){toast('This shelf is already full!');return}const qty=Math.min(carried,it.shelf.max-it.shelf.stock);it.shelf.stock+=qty;carried-=qty;setStockVisual(it.shelf);toast(`Restocked ${qty} items on the ${['snack','pantry','drinks','fresh'][it.shelf.index%4]} shelf!`)}
 if(it.action==='checkout'){if(!queue.length){toast('No customers in line just yet.');return}const c=queue.shift();c.state='leave';c.target={x:0,z:9.2};c.wait=0;const sale=12+Math.floor(Math.random()*7);earnings+=sale;served++;completed++;refreshQueue();toast(`Cha-ching! ${money(sale)} sale — thanks for shopping!`);if(earnings>=350&&!dayWon){dayWon=true;toast('Daily goal reached! You’re the neighborhood favorite! 🎉')}}
 updateHUD()}
function updateHUD(){document.getElementById('cash').textContent=money(earnings);document.getElementById('shoppers').textContent=String(customers.filter(c=>c.state!=='leave').length);const f=Math.min(100,earnings/350*100);document.getElementById('goal-fill').style.width=f+'%';document.getElementById('goal-text').textContent=`${money(earnings)} / $350`;const mins=Math.floor(gameSeconds/60),hh=8+Math.floor(mins/60),mm=mins%60;document.getElementById('clock').textContent=`${String(hh%12||12).padStart(2,'0')}:${String(mm).padStart(2,'0')} ${hh>=12?'PM':'AM'}`;const it=currentInteraction();const panel=document.getElementById('interaction');if(started&&it){panel.classList.add('show');document.getElementById('action-title').textContent=it.title;document.getElementById('action-detail').textContent=it.detail;document.querySelector('.interact-key').textContent='E'}else panel.classList.remove('show');document.getElementById('tip').textContent=carried?`You’re carrying ${carried} items — fill up an empty shelf!`:queue.length?`A customer is ready at checkout!`:`A well-stocked shelf keeps the cash flowing!`}

const keys={};window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.code==='KeyE'&&!e.repeat&&started)interact();if(e.code==='Escape'&&started)toast('Your shop is open — take your time!')});window.addEventListener('keyup',e=>keys[e.code]=false);
document.getElementById('play').addEventListener('click',()=>{started=true;document.getElementById('intro').classList.add('hidden');spawnCustomer();setTimeout(spawnCustomer,1700);toast('The doors are open! Welcome your first shoppers.');updateHUD()});
// Accessible thumb joystick plus large mobile action buttons.
const joystick=document.getElementById('joystick'),stick=document.getElementById('stick');let joy={x:0,y:0},joyPointer=null;
function joyMove(e){const r=joystick.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=36,len=Math.hypot(dx,dy),k=len>max?max/len:1;joy.x=dx*k/max;joy.y=dy*k/max;stick.style.transform=`translate(${joy.x*36}px,${joy.y*36}px)`}
joystick.addEventListener('pointerdown',e=>{joyPointer=e.pointerId;joystick.setPointerCapture(e.pointerId);joyMove(e)});joystick.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)joyMove(e)});const joyEnd=()=>{joy={x:0,y:0};joyPointer=null;stick.style.transform='translate(0,0)'};joystick.addEventListener('pointerup',joyEnd);joystick.addEventListener('pointercancel',joyEnd);
document.getElementById('use-btn').addEventListener('pointerdown',e=>{e.preventDefault();if(started)interact()});const sprintBtn=document.getElementById('sprint-btn');sprintBtn.addEventListener('pointerdown',e=>{e.preventDefault();keys.ShiftLeft=true});sprintBtn.addEventListener('pointerup',()=>keys.ShiftLeft=false);sprintBtn.addEventListener('pointercancel',()=>keys.ShiftLeft=false);

function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)}window.addEventListener('resize',resize);
let last=performance.now(),spawnTimer=0,hudTimer=0;
function animate(now){requestAnimationFrame(animate);const dt=Math.min(.05,(now-last)/1000);last=now;
 if(started){gameSeconds+=dt*60;spawnTimer+=dt;if(spawnTimer>=nextSpawn){spawnTimer=0;nextSpawn=6+Math.random()*5;spawnCustomer()}
  let mx=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+joy.x;let mz=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0)+joy.y;const len=Math.hypot(mx,mz);if(len>1){mx/=len;mz/=len}const speed=(keys.ShiftLeft||keys.ShiftRight?6.7:4.15);player.position.x=THREE.MathUtils.clamp(player.position.x+mx*speed*dt,-11.3,11.3);player.position.z=THREE.MathUtils.clamp(player.position.z+mz*speed*dt,-8.7,8.5);if(len>.08){playerModel.rotation.y=Math.atan2(mx,mz);playerModel.position.y=Math.sin(now*.012)*.035}
  customers.forEach((c)=>{if(c.state==='leave'){const t=c.target;const dx=t.x-c.group.position.x,dz=t.z-c.group.position.z,d=Math.hypot(dx,dz);if(d<.3){if(t.z>9){scene.remove(c.group);c.state='gone';return}}else{c.group.position.x+=dx/d*2.35*dt;c.group.position.z+=dz/d*2.35*dt}}
   else if(c.state==='toShelf'){const t={x:c.shelf.x,z:c.shelf.z+1.2};const dx=t.x-c.group.position.x,dz=t.z-c.group.position.z,d=Math.hypot(dx,dz);if(d<.28){c.state='browse';c.wait=1.6+Math.random()*1.7}else{c.group.position.x+=dx/d*1.8*dt;c.group.position.z+=dz/d*1.8*dt}}
   else if(c.state==='browse'){c.wait-=dt;if(c.wait<=0){if(c.shelf.stock>0){const bought=Math.min(c.shelf.stock,1+Math.floor(Math.random()*2));c.shelf.stock-=bought;setStockVisual(c.shelf);c.bag=true;c.group.userData.bag.visible=true;c.state='toQueue'}else{c.state='toQueue';c.bag=false;c.group.userData.bag.visible=false}if(c.state==='toQueue'){c.target={x:7.7,z:3.85+queue.length*1.08};c.state='toQueue'}}}
   else if(c.state==='toQueue'){const t=c.target||{x:7.7,z:3.85+queue.length*1.08};const dx=t.x-c.group.position.x,dz=t.z-c.group.position.z,d=Math.hypot(dx,dz);if(d<.22){c.state='queue';queue.push(c);refreshQueue()}else{c.group.position.x+=dx/d*2.2*dt;c.group.position.z+=dz/d*2.2*dt}}
  });
  for(let i=customers.length-1;i>=0;i--)if(customers[i].state==='gone')customers.splice(i,1);
  // Subtle product bobbing makes the store feel alive.
  for(const s of shelves)for(const p of s.products)if(p.visible)p.position.y=p.userData.baseY+Math.sin(now*.002+p.userData.phase)*.012;
  hudTimer+=dt;if(hudTimer>.12){hudTimer=0;updateHUD()}
 }
 const targetX=player.position.x*.42,targetZ=player.position.z*.35;camera.position.x+=(targetX-camera.position.x)*Math.min(1,dt*2);camera.position.z+=(21+targetZ-camera.position.z)*Math.min(1,dt*2);camera.lookAt(player.position.x*.18,0,player.position.z*.15);
 renderer.render(scene,camera)}requestAnimationFrame(animate);
</script>
</body>
</html>

